mapper.select:
SELECT COALESCE(SUM(quantity),0) FROM inventory_line_credits
WHERE order_id=#{orderId} AND product_id=#{productId} AND kind=#{kind}
  AND COALESCE(warehouse_id,1)=#{warehouseId}

SELECT COALESCE(SUM(l.quantity),0) FROM inventory_outbound_lines l
JOIN inventory_outbound_documents d ON d.outbound_id=l.outbound_id
WHERE d.order_id=#{orderId} AND d.merchant_id=#{merchantId}
  AND l.order_line_id=#{orderLineId} AND l.product_id=#{productId}
  AND d.warehouse_id=COALESCE(#{warehouseId},1)
AND d.outbound_id=#{outboundId}

SELECT d.warehouse_id,d.outbound_id,l.quantity
FROM inventory_outbound_lines l JOIN inventory_outbound_documents d ON d.outbound_id=l.outbound_id
WHERE d.order_id=#{orderId} AND d.merchant_id=#{merchantId}
  AND l.order_line_id=#{orderLineId} AND l.product_id=#{productId}
AND d.warehouse_id=#{warehouseId}
AND d.outbound_id=#{outboundId}
ORDER BY d.outbound_id
